#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;
int main(){ int n, limit; if(!(cin>>n>>limit)) return 0; vector<int> w(n); for(int i=0;i<n;i++) cin>>w[i]; sort(w.begin(), w.end()); int i=0, ans=0; while(i<n){ if(i+1<n && w[i]+w[i+1]<=limit) i+=2; else i++; ans++; } cout<<ans<<'\n'; return 0; }
